// C++ wrapper around the acados solver generated by scripts/export_c_code.py: same
// reference, initialisation and time-shifted warm start as anmpc.nmpc.NMPC
// (checked in test/test_solver.cpp).
#pragma once

#include <optional>

#include "arm_nmpc_ros/arm_model.hpp"
#include "arm_nmpc_ros/inner_loop.hpp"

namespace arm_nmpc
{

struct SolveResult
{
  Vec7 tau{};  // torque of the first interval (= plan.tau[0])
  // first kPlanNodes intervals of the plan (node 0 = the state solved for); plan.gain = the
  // stage-0 feedback of the QP just solved, tau(x0 + dx) = tau + K dx (if computed)
  Plan plan;
  double solve_time_ms = 0;
  double gain_time_ms = 0;
  int status = 0;
};

class NmpcSolver
{
public:
  explicit NmpcSolver(Circle circle);
  ~NmpcSolver();
  NmpcSolver(const NmpcSolver &) = delete;
  NmpcSolver & operator=(const NmpcSolver &) = delete;

  // friction the model compensates: tau_f = fv dq + fc tanh(dq / eps_model)
  void set_friction_model(const Vec7 & fv, const Vec7 & fc);
  void set_circle(const Circle & c) {circle_ = c; initialized_ = false;}
  // also compute the stage-0 feedback gain in step() (as anmpc.nmpc.NMPC.feedback_gain)
  void set_compute_gain(bool on) {compute_gain_ = on;}

  SolveResult step(double t, const Vec7 & q, const Vec7 & dq);

private:
  void shift(double dt);
  void set_x0(const double * x);
  void feedback_gain(Gain & K);

  void * capsule_ = nullptr;
  Circle circle_;
  Dynamics dyn_;
  bool initialized_ = false;
  bool compute_gain_ = false;
  std::optional<double> t_last_;
  double offsets_[params::N + 1];
};

}  // namespace arm_nmpc
